  end if;
  if b.bundle_kind<>'combat' or b.mechanical_template_id is null
    or b.mechanical_version_id is null or b.mechanical_binding_id is null
    then raise exception 'MF_NPC_KIND_STALE' using errcode='55000';end if;
  select * into n from public.nb_templates where id=b.template_id;
  select * into nv from public.nb_template_versions where id=b.narrative_version_id and template_id=b.template_id;
