     or nv.id is null or nv.review_state<>'approved'
     or not ('narrator_adapter'=any(b.consumer_scopes))
     or b.dependency_manifest->>'certified_payload_sha256'<>png_builder_internal.sha(b.certified_payload)
     or coalesce(b.bundle_sha256,'') !~ '^[0-9a-f]{64}$'
     or cardinality(b.media_ids)<>(select count(*)::integer from public.nb_template_media_versions med
       where med.id=any(b.media_ids) and med.template_id=b.template_id
         and med.template_version_id=b.narrative_version_id and med.sha256 ~ '^[0-9a-f]{64}$')
     then raise exception 'MF_NPC_NARRATIVE_STALE' using errcode='55000'; end if;
