    if not ('combat_v2'=any(b.consumer_scopes)) or not ('master_v2'=any(b.consumer_scopes)) or not (coalesce(b.certified_payload#>'{document,consumer_scopes}','[]'::jsonb) ? 'combat_v2')
       then raise exception 'MF_NPC_COMBAT_SCOPE' using errcode='55000'; end if;
